1	/**
2	 * Translate DeepSeek SSE payloads with one stateful harness block per content, reasoning, or tool
3	 * call index. An empty initial reasoning delta does not open a block. Finish reason and the latest
4	 * usage are deferred until `[DONE]`, covering both finish-attached and trailing usage-only shapes
5	 * while ensuring no chunk follows `finish`.
6	 *
7	 * Translate DeepSeek wire chunks into the harness `StreamChunk` protocol.
8	 * @module dsh-llm-deepseek/translate
9	 */
10	
11	import { CallId, EMPTY_RESPONSE_CODE, LlmError } from '@deepseek-ai/dsh-llm'
12	import type { ContentBlock, FinishReason, StreamChunk, TokenUsage } from '@deepseek-ai/dsh-llm'
13	import { DONE } from './sse.ts'
14	import type { WireChunk, WireUsage } from './types.ts'
15	
16	/** One open block under assembly. */
17	interface OpenBlock {
18	  index: number
19	  kind: 'text' | 'reasoning' | 'tool-call'
20	  text: string
21	  /** tool-call only */
22	  callId?: string
23	  name?: string
24	}
25	
26	/**
27	 * Map the wire finish_reason vocabulary to the harness FinishReason.
28	 * @param reason - the wire `finish_reason` string.
29	 * @returns the mapped reason; unrecognized values (content_filter, …) become `{kind: 'error'}` with the uppercased value as `code`.
30	 */
31	export function mapFinishReason(reason: string): FinishReason {
32	  switch (reason) {
33	    case 'stop': return { kind: 'stop' }
34	    case 'tool_calls': return { kind: 'tool-calls' }
35	    case 'length': return { kind: 'max-tokens' }
36	    default:
37	      // content_filter, insufficient_system_resource, future additions.
38	      return {
39	        kind: 'error',
40	        failure: { message: `model stopped: ${reason}`, code: reason.toUpperCase() },
41	      }
42	  }
43	}
44	
45	/**
46	 * Map wire usage fields. DeepSeek's `prompt_tokens` INCLUDES cache hits
47	 * (`prompt_tokens = prompt_cache_hit_tokens + prompt_cache_miss_tokens`,
48	 * api/create-chat-completion); the harness TokenUsage convention is
49	 * DISJOINT counts, so cache reads are subtracted out of `inputTokens`.
50	 * @param usage - wire usage from the finish chunk or the trailing usage-only chunk.
51	 * @returns disjoint harness counts; cache/reasoning fields present only when the wire reported them.
52	 */
53	export function mapUsage(usage: WireUsage): TokenUsage {
54	  const cacheRead = usage.prompt_tokens_details?.cached_tokens ?? usage.prompt_cache_hit_tokens
55	  const reasoning = usage.completion_tokens_details?.reasoning_tokens
56	  return {
57	    inputTokens: usage.prompt_tokens - (cacheRead ?? 0),
58	    outputTokens: usage.completion_tokens,
59	    ...cacheRead !== undefined ? { cacheReadTokens: cacheRead } : {},
60	    ...reasoning !== undefined ? { reasoningTokens: reasoning } : {},
61	  }
62	}
63	
64	/** Assemble the final ContentBlock for one open block. */
65	function closeBlock(block: OpenBlock): ContentBlock {
66	  switch (block.kind) {
67	    case 'text': return { type: 'text', text: block.text }
68	    case 'reasoning': return { type: 'reasoning', text: block.text }
69	    case 'tool-call': return {
70	      type: 'tool-call',
71	      id: CallId(block.callId ?? ''),
72	      name: block.name ?? '',
73	      arguments: block.text,
74	    }
75	  }
76	}
